import numpy as np
from collections import Counter

def make_state(a, b, c, prev_c=None, include_agent_prev=True):
    x = np.zeros(500)
    # wall border in channel 3
    for r in range(10):
        for col in range(10):
            if r == 0 or r == 9 or col == 0 or col == 9:
                x[(r * 10 + col) * 5 + 3] = 1
    # agent at (a, 1)
    x[(a * 10 + 1) * 5 + 0] = 1
    # ball at (b, c)
    x[(b * 10 + c) * 5 + 1] = 1
    # previous frame: agent stayed put, ball moved from prev_c to c
    if include_agent_prev:
        x[(a * 10 + 1) * 5 + 4] = 1
    if prev_c is not None:
        x[(b * 10 + prev_c) * 5 + 4] = 1
    return x

