import numpy as np
from collections import Counter

def build(ar, br, bc, prev_bc):
    x = np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                x[(r * 10 + c) * 5 + 3] = 1          # wall border
    x[(ar * 10 + 1) * 5 + 0] = 1                  # agent at (ar,1)
    x[(br * 10 + bc) * 5 + 1] = 1                 # ball at (br,bc)
    x[(ar * 10 + 1) * 5 + 4] = 1                  # prev agent (stationary)
    x[(br * 10 + prev_bc) * 5 + 4] = 1            # prev ball
    return x

# (ball column, direction, previous ball column)
conditions = [(2, 'L', 3), (3, 'L', 4), (4, 'L', 5), (3, 'R', 2), (4, 'R', 3)]

states, meta = [], []
for (bc, d, pbc) in conditions:
    for ar in range(2, 8):
        for br in range(1, 9):
            states.append(build(ar, br, bc, pbc))
            meta.append((bc, d, ar, br))

X = np.array(states)                              # 240 rows, one forward pass
out = forward(X)
acts = out.argmax(axis=1)

def expected(ar, br):
    return 1 if br < ar else (2 if br > ar else 0)   # up / down / noop

print("Pong-style tracking accuracy (up if ball above, down if below, noop if level):")
for (bc, d, pbc) in conditions:
    c = t = 0
    for i, (b, dd, ar, br) in enumerate(meta):
        if b == bc and dd == d:
            t += 1
            if acts[i] == expected(ar, br):
                c += 1
    print(f"  ball col {bc} moving {d}: {c}/{t} = {c/t:.2f}")

print("\nAction table, ball col 2 moving L (rows = agent row 2-7, cols = ball row 1-8):")
